def count_distinct_sets(n):
    distinct_sets = set()
    for x in range(n):
        for y in range(n):
            for z in range(n):
                # The three indices are (y,z), (x,z), (x,y)
                # We represent each as a single integer: y*n + z
                s = frozenset([(y, z), (x, z), (x, y)])
                distinct_sets.add(s)
    return len(distinct_sets)

for n in [2, 3, 4, 5]:
    print(f"n={n}, distinct_sets={count_distinct_sets(n)}")

def count_distinct_sets_v2(n):
    distinct_sets = set()
    for x in range(n):
        for y in range(n):
            for z in range(n):
                # The three indices are (y,z), (x,z), (x,y)
                # Each pair (a,b) is a unique index from 0 to n^2-1.
                s = frozenset([(y, z), (x, z), (x, y)])
                distinct_sets.add(s)
    return len(distinct_sets)

for n in [2, 3, 4, 5]:
    print(f"n={n}, distinct_sets={count_distinct_sets_v2(n)}")

def count_distinct_sets_v3(n):
    distinct_sets = set()
